1	use anyhow::Result;
2	
3	use ruff_macros::{ViolationMetadata, derive_message_formats};
4	use ruff_python_ast::name::QualifiedName;
5	use ruff_python_ast::{self as ast, Expr, Operator};
6	use ruff_python_semantic::{Modules, SemanticModel};
7	use ruff_text_size::Ranged;
8	
9	use crate::Violation;
10	use crate::checkers::ast::Checker;
11	
12	/// ## What it does
13	/// Checks for files with overly permissive permissions.
14	///
15	/// ## Why is this bad?
16	/// Overly permissive file permissions may allow unintended access and
17	/// arbitrary code execution.
18	///
19	/// ## Example
20	/// ```python
21	/// import os
22	///
23	/// os.chmod("/etc/secrets.txt", 0o666)  # rw-rw-rw-
24	/// ```
25	///
26	/// Use instead:
27	/// ```python
28	/// import os
29	///
30	/// os.chmod("/etc/secrets.txt", 0o600)  # rw-------
31	/// ```
32	///
33	/// ## References
34	/// - [Python documentation: `os.chmod`](https://docs.python.org/3/library/os.html#os.chmod)
35	/// - [Python documentation: `stat`](https://docs.python.org/3/library/stat.html)
36	/// - [Common Weakness Enumeration: CWE-732](https://cwe.mitre.org/data/definitions/732.html)
37	#[derive(ViolationMetadata)]
38	#[violation_metadata(stable_since = "v0.0.211")]
39	pub(crate) struct BadFilePermissions {
40	    reason: Reason,
41	}
42	
43	impl Violation for BadFilePermissions {
44	    #[derive_message_formats]
45	    fn message(&self) -> String {
46	        let BadFilePermissions { reason } = self;
47	        match reason {
48	            Reason::Permissive(mask) => {
49	                format!("`os.chmod` setting a permissive mask `{mask:#o}` on file or directory")
50	            }
51	            Reason::Invalid => {
52	                "`os.chmod` setting an invalid mask on file or directory".to_string()
53	            }
54	        }
55	    }
56	}
57	
58	#[derive(Debug, PartialEq, Eq)]
59	enum Reason {
60	    Permissive(u16),
61	    Invalid,
62	}
63	
64	/// S103
65	pub(crate) fn bad_file_permissions(checker: &Checker, call: &ast::ExprCall) {
66	    if !checker.semantic().seen_module(Modules::OS) {
67	        return;
68	    }
69	
70	    if checker
71	        .semantic()
72	        .resolve_qualified_name(&call.func)
73	        .is_some_and(|qualified_name| matches!(qualified_name.segments(), ["os", "chmod"]))
74	    {
75	        if let Some(mode_arg) = call.arguments.find_argument_value("mode", 1) {
76	            match parse_mask(mode_arg, checker.semantic()) {
77	                // The mask couldn't be determined (e.g., it's dynamic).
78	                Ok(None) => {}
79	                // The mask is a valid integer value -- check for overly permissive permissions.
80	                Ok(Some(mask)) => {
81	                    if (mask & WRITE_WORLD > 0) || (mask & EXECUTE_GROUP > 0) {
82	                        checker.report_diagnostic(
83	                            BadFilePermissions {
84	                                reason: Reason::Permissive(mask),
85	                            },
86	                            mode_arg.range(),
87	                        );
88	                    }
89	                }
90	                // The mask is an invalid integer value (i.e., it's out of range).
91	                Err(_) => {
92	                    checker.report_diagnostic(
93	                        BadFilePermissions {
94	                            reason: Reason::Invalid,
95	                        },
96	                        mode_arg.range(),
97	                    );
98	                }
99	            }
100	        }
101	    }
102	}
103	
104	const WRITE_WORLD: u16 = 0o2;
105	const EXECUTE_GROUP: u16 = 0o10;
106	
107	fn py_stat(qualified_name: &QualifiedName) -> Option<u16> {
108	    match qualified_name.segments() {
109	        ["stat", "ST_MODE"] => Some(0o0),
110	        ["stat", "S_IFDOOR"] => Some(0o0),
111	        ["stat", "S_IFPORT"] => Some(0o0),
112	        ["stat", "ST_INO"] => Some(0o1),
113	        ["stat", "S_IXOTH"] => Some(0o1),
114	        ["stat", "UF_NODUMP"] => Some(0o1),
115	        ["stat", "ST_DEV"] => Some(0o2),
116	        ["stat", "S_IWOTH"] => Some(0o2),
117	        ["stat", "UF_IMMUTABLE"] => Some(0o2),
118	        ["stat", "ST_NLINK"] => Some(0o3),
119	        ["stat", "ST_UID"] => Some(0o4),
120	        ["stat", "S_IROTH"] => Some(0o4),
121	        ["stat", "UF_APPEND"] => Some(0o4),
122	        ["stat", "ST_GID"] => Some(0o5),
123	        ["stat", "ST_SIZE"] => Some(0o6),
124	        ["stat", "ST_ATIME"] => Some(0o7),
125	        ["stat", "S_IRWXO"] => Some(0o7),
126	        ["stat", "ST_MTIME"] => Some(0o10),
127	        ["stat", "S_IXGRP"] => Some(0o10),
128	        ["stat", "UF_OPAQUE"] => Some(0o10),
129	        ["stat", "ST_CTIME"] => Some(0o11),
130	        ["stat", "S_IWGRP"] => Some(0o20),
131	        ["stat", "UF_NOUNLINK"] => Some(0o20),
132	        ["stat", "S_IRGRP"] => Some(0o40),
133	        ["stat", "UF_COMPRESSED"] => Some(0o40),
134	        ["stat", "S_IRWXG"] => Some(0o70),
135	        ["stat", "S_IEXEC"] => Some(0o100),
136	        ["stat", "S_IXUSR"] => Some(0o100),
137	        ["stat", "S_IWRITE"] => Some(0o200),
138	        ["stat", "S_IWUSR"] => Some(0o200),
139	        ["stat", "S_IREAD"] => Some(0o400),
140	        ["stat", "S_IRUSR"] => Some(0o400),
141	        ["stat", "S_IRWXU"] => Some(0o700),
142	        ["stat", "S_ISVTX"] => Some(0o1000),
143	        ["stat", "S_ISGID"] => Some(0o2000),
144	        ["stat", "S_ENFMT"] => Some(0o2000),
145	        ["stat", "S_ISUID"] => Some(0o4000),
146	        _ => None,
147	    }
148	}
149	
150	/// Return the mask value as a `u16`, if it can be determined. Returns an error if the mask is
151	/// an integer value, but that value is out of range.
152	fn parse_mask(expr: &Expr, semantic: &SemanticModel) -> Result<Option<u16>> {
153	    match expr {
154	        Expr::NumberLiteral(ast::ExprNumberLiteral {
155	            value: ast::Number::Int(int),
156	            ..
157	        }) => match int.as_u16() {
158	            Some(value) => Ok(Some(value)),
159	            None => anyhow::bail!("int value out of range"),
160	        },
161	        Expr::Attribute(_) => Ok(semantic
162	            .resolve_qualified_name(expr)
163	            .as_ref()
164	            .and_then(py_stat)),
165	        Expr::BinOp(ast::ExprBinOp {
166	            left,
167	            op,
168	            right,
169	            range: _,
170	            node_index: _,
171	        }) => {
172	            let Some(left_value) = parse_mask(left, semantic)? else {
173	                return Ok(None);
174	            };
175	            let Some(right_value) = parse_mask(right, semantic)? else {
176	                return Ok(None);
177	            };
178	            Ok(match op {
179	                Operator::BitAnd => Some(left_value & right_value),
180	                Operator::BitOr => Some(left_value | right_value),
181	                Operator::BitXor => Some(left_value ^ right_value),
182	                _ => None,
183	            })
184	        }
185	        _ => Ok(None),
186	    }
187	}
